import{at as e,it as t,n,vt as r}from"./chunks/framework.yntlMcNk.js";var i=JSON.parse(`{"title":"Portal","description":"","frontmatter":{"title":"Portal","covers":{"screens":["SCR-050"],"stories":["US-127"]}},"headers":[],"relativePath":"usage/portal.md","filePath":"usage/portal.md"}`),a={name:`usage/portal.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="portal" tabindex="-1">Portal <a class="header-anchor" href="#portal" aria-label="Permalink to “Portal”">​</a></h1><p>The portal shows the shared catalogs of the repository read-only. It is meant for people who read the architecture but do not work on it, for example with the role <code>portal-reader</code>. Everybody with the permission <code>portal:read</code> can open it; the roles <code>viewer</code>, <code>analyst</code> and <code>enterprise-architect</code> have it too.</p><h2 id="open-the-portal" tabindex="-1">Open the portal <a class="header-anchor" href="#open-the-portal" aria-label="Permalink to “Open the portal”">​</a></h2><ul><li>With only <code>portal:read</code> (for example the role <code>portal-reader</code>), you land on the portal after login. The header shows <em>Portal</em> as its only entry; the start page and the catalogs lead to the portal as well.</li><li>With <code>entity:read</code>, the header shows <em>Portal</em> next to <em>Catalogs</em>.</li></ul><p>The page <em>Portal</em> lists the <strong>shared catalogs</strong> by name, each with its entity type. Personal catalogs never appear in the portal, not even your own.</p><h2 id="read-a-catalog" tabindex="-1">Read a catalog <a class="header-anchor" href="#read-a-catalog" aria-label="Permalink to “Read a catalog”">​</a></h2><p>Choose a catalog in the list. It opens with the columns, the default sort and the default join mode its owner configured.</p><ul><li><strong>Sort:</strong> choose a column header. The first click sorts ascending, the second descending, the third returns to the default order.</li><li><strong>Page:</strong> the table shows 50 rows per page; the page numbers below the table move between pages.</li><li><strong>Back:</strong> <em>Back to the portal</em> returns to the list.</li></ul><p>Sort and page are part of the address, so you can bookmark a sorted page or send it to someone. The portal offers no action that changes the catalog: no columns, joins, filters, views or navigation tree. If a catalog is no longer shared or does not exist, the page says <em>Catalog not found</em>.</p><p>The portal applies the <a href="./../administration/property-visibility">property visibility</a> like every catalog: a column on a property you may not see stays empty, and a column on a connection-based property shows the value only in the rows of entities connected to your element.</p><h2 id="through-the-api" tabindex="-1">Through the API <a class="header-anchor" href="#through-the-api" aria-label="Permalink to “Through the API”">​</a></h2><ul><li><code>GET /portal/catalogs</code> lists the shared catalogs, ordered by name.</li><li><code>GET /portal/catalogs/{id}/query</code> returns one page of a shared catalog with <code>page</code>, <code>pageSize</code> (at most 200) and <code>sort</code> (<code>{column}:{asc|desc}</code>), the same result as <code>GET /catalogs/{id}/query</code> without filters, join mode overrides or views.</li><li>The next page can be read with <code>cursor</code> (the <code>nextCursor</code> of the previous page) and <code>page</code> + 1, and a query above the time limit answers 503 <code>query-timeout</code>, as in the catalog query (see <a href="./catalogs#browse">Catalogs</a>). A cursor of the catalog query is not valid in the portal. Columns on properties you may not see are empty, as in the catalog query.</li></ul><p>Both need <code>portal:read</code>. A personal catalog answers 404, an invalid parameter 400 with the parameter in <code>invalidFields</code>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};